BEGIN; DO $guard$ DECLARE r record; n bigint; BEGIN IF (SELECT count(*) FROM auth.users WHERE id IN ('fb814dde-73df-4483-979b-157f457b9591','3e775ca1-0e1c-4e91-ab24-66a32e78becb','ba8a30a3-9b9c-496f-81d7-282f3098e818','d285fdee-e3e3-451c-9bd4-33d0c5f032f2','ab430705-55b8-41dd-bb9d-2227d5561eab','f01a1f5e-7374-4904-a930-02166f035d50'))<>6 THEN RAISE EXCEPTION 'Unexpected cohort'; END IF; FOR r IN SELECT table_name FROM information_schema.columns WHERE table_schema='public' AND column_name='user_id' LOOP EXECUTE format('SELECT count(*) FROM public.%I WHERE user_id IN (''fb814dde-73df-4483-979b-157f457b9591'',''3e775ca1-0e1c-4e91-ab24-66a32e78becb'',''ba8a30a3-9b9c-496f-81d7-282f3098e818'',''d285fdee-e3e3-451c-9bd4-33d0c5f032f2'',''ab430705-55b8-41dd-bb9d-2227d5561eab'',''f01a1f5e-7374-4904-a930-02166f035d50'')',r.table_name) INTO n; IF n>0 AND r.table_name NOT IN ('accounts','company_payment_account_roles') THEN RAISE EXCEPTION 'Unexpected dependent data in %',r.table_name; END IF; END LOOP; IF EXISTS(SELECT 1 FROM accounts WHERE user_id IN ('fb814dde-73df-4483-979b-157f457b9591','3e775ca1-0e1c-4e91-ab24-66a32e78becb','ba8a30a3-9b9c-496f-81d7-282f3098e818','d285fdee-e3e3-451c-9bd4-33d0c5f032f2','ab430705-55b8-41dd-bb9d-2227d5561eab','f01a1f5e-7374-4904-a930-02166f035d50') AND (id<>'kan113-sale' OR name<>'KAN113 synthetic')) THEN RAISE EXCEPTION 'Unexpected account'; END IF; END $guard$; DELETE FROM auth.users WHERE id IN ('fb814dde-73df-4483-979b-157f457b9591','3e775ca1-0e1c-4e91-ab24-66a32e78becb','ba8a30a3-9b9c-496f-81d7-282f3098e818','d285fdee-e3e3-451c-9bd4-33d0c5f032f2','ab430705-55b8-41dd-bb9d-2227d5561eab','f01a1f5e-7374-4904-a930-02166f035d50'); SELECT json_build_object('synthetic_auth_residual',(SELECT count(*) FROM auth.users WHERE id IN ('fb814dde-73df-4483-979b-157f457b9591','3e775ca1-0e1c-4e91-ab24-66a32e78becb','ba8a30a3-9b9c-496f-81d7-282f3098e818','d285fdee-e3e3-451c-9bd4-33d0c5f032f2','ab430705-55b8-41dd-bb9d-2227d5561eab','f01a1f5e-7374-4904-a930-02166f035d50')),'profiles_residual',(SELECT count(*) FROM profiles WHERE id IN ('fb814dde-73df-4483-979b-157f457b9591','3e775ca1-0e1c-4e91-ab24-66a32e78becb','ba8a30a3-9b9c-496f-81d7-282f3098e818','d285fdee-e3e3-451c-9bd4-33d0c5f032f2','ab430705-55b8-41dd-bb9d-2227d5561eab','f01a1f5e-7374-4904-a930-02166f035d50')),'accounts_residual',(SELECT count(*) FROM accounts WHERE user_id IN ('fb814dde-73df-4483-979b-157f457b9591','3e775ca1-0e1c-4e91-ab24-66a32e78becb','ba8a30a3-9b9c-496f-81d7-282f3098e818','d285fdee-e3e3-451c-9bd4-33d0c5f032f2','ab430705-55b8-41dd-bb9d-2227d5561eab','f01a1f5e-7374-4904-a930-02166f035d50'))); COMMIT;